   if(status==='SUBSCRIBED'){const {error}=await channel.track({id:player,name:players[player].name,userId:authUserId,joinedAt:Date.now()});if(error){say('Não foi possível anunciar sua presença na sala: '+error.message);return}await touchPlayer();if(heartbeatTimer)clearInterval(heartbeatTimer);heartbeatTimer=setInterval(async()=>{await touchPlayer();await refreshHostRole()},25000);const wasActiveRoom=restoringGame;await refreshRosterFromServer();let restored=false;try{restored=await restoreActiveGame()}catch(e){console.warn('Falha ao restaurar a partida:',e);say('Não foi possível recuperar a rodada salva. Saia e entre novamente; a sala não foi reiniciada.');restoreFailed=true}if(wasActiveRoom&&!restored){restoreFailed=true;say('Não foi possível recuperar esta rodada. A sala não foi reiniciada; saia e tente entrar novamente.')}restoringGame=false;render();if(game.phase==='draw')startTimer(game.duration||120);else if(game.phase==='vote'){startVoteTimer();loadOwnVote()}if(!restoreFailed)if(!restoreFailed){say('Conectado à sala '+room+'.');if(game.phase==='draw')send('request-canvas-snapshots',{round:game.round})}if(isHost&&!restoreFailed){syncState();sendCurrentDrawings();sendPodiumArt()}}
   else if(status==='CHANNEL_ERROR'||status==='TIMED_OUT')say('Conexão instável. O navegador tentará restabelecer a conexão; se não voltar, saia e entre novamente.');
