function pickTheme(){const options=THEMES.filter(t=>!(game.usedThemes||[]).includes(t.name));return options[Math.floor(Math.random()*options.length)]||THEMES[Math.floor(Math.random()*THEMES.length)]}
async function startFirstRound(){if(!isHost||game.phase!=='lobby'||restoreFailed)return;const chosen=pickTheme();game.phase='ready';game.round=1;game.theme=chosen.name;game.reference=refImage(chosen);game.duration=Number($('roundDuration').value)||120;game.usedThemes=[chosen.name];game.drawings={};game.votes={};game.lastTally={};game.winners=[];game.resultMessage='';game.podiumDrawings={};game.roundId=null;game.deadlineAt=null;game.readyDeadline=Date.now()+5000;drawDeadlineExpired=false;drawForceVote=false;submitted=false;resetDrawing();syncState();render();startReadyTimer()}
