function startReadyTimer(){if(timer)clearInterval(timer);const deadline=Number(game.readyDeadline)||Date.now()+5000;const token=++roundToken;const tick=()=>{if(token!==roundToken)return;seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('countdown').textContent=seconds+'s';if(seconds<=0){clearInterval(timer);timer=null;if(isHost&&game.phase==='ready')startDrawingPhase()}};tick();timer=setInterval(tick,250)}
async function startDrawingPhase(){if(!isHost||game.phase!=='ready')return;const dbRoundNumber=dbRoundBase+game.round;if(dbRoundNumber>20){say('Esta sala atingiu o limite de rodadas salvas. Crie uma nova sala para continuar.');return}const visibleDeadline=Date.now()+(Number(game.duration)||120)*1000;const databaseDeadline=visibleDeadline+15000;const prompt=JSON.stringify({theme:game.theme,reference:game.reference});const {data,error}=await sb.from('game_rounds').insert({room_id:dbRoomId,round_number:dbRoundNumber,prompt,status:'draw',starts_at:new Date().toISOString(),deadline_at:new Date(databaseDeadline).toISOString()}).select('id').single();if(error){say('Não foi possível iniciar a rodada no banco: '+error.message);return}dbRoundId=data.id;lastDbRoundNumber=dbRoundNumber;game.roundId=dbRoundId;game.deadlineAt=visibleDeadline;game.phase='draw';game.drawings={};game.votes={};game.voteDeadline=0;drawDeadlineExpired=false;drawForceVote=false;submissionInFlight=false;submitted=false;roomSettings={...roomSettings,matchBaseRound:dbRoundBase,duration:game.duration,totalRounds:TOTAL_ROUNDS};const roomResult=await sb.from('game_rooms').update({status:'draw',round_number:dbRoundNumber,current_prompt:game.theme,deadline_at:new Date(databaseDeadline).toISOString(),settings:roomSettings}).eq('id',dbRoomId);if(roomResult.error)console.warn('Não foi possível atualizar o estado da sala:',roomResult.error.message);syncState();render();startTimer(game.duration||120)}
function startTimer(value){if(timer)clearInterval(timer);const deadline=Number(game.deadlineAt)||Date.now()+value*1000;const token=++roundToken;const tick=()=>{if(token!==roundToken)return;seconds=Math.max(0,Math.ceil((deadline-Date.now())/1000));$('countdown').textContent=seconds+'s';if(seconds<=0){clearInterval(timer);timer=null;if(game.phase==='draw'){drawDeadlineExpired=true;if(!submitted)submitDrawing(true);if(isHost){if(drawGraceTimer)clearTimeout(drawGraceTimer);drawGraceTimer=setTimeout(()=>{drawForceVote=true;if(game.phase==='draw'&&!submissionInFlight)beginVote();else if(game.phase==='draw'&&submissionInFlight){const wait=()=>{if(game.phase!=='draw')return;if(submissionInFlight){drawGraceTimer=setTimeout(wait,1000);return}beginVote()};wait()}},9000)}}else if(game.phase==='vote'&&isHost)finishRound()}};tick();timer=setInterval(tick,250)}
async function beginVote(){if(!isHost||game.phase!=='draw'||finishingRound)return;if(drawGraceTimer&&!drawForceVote&&drawDeadlineExpired)return;if(timer){clearInterval(timer);timer=null}if(drawGraceTimer&&!drawForceVote)clearTimeout(drawGraceTimer);try{const deadline=Date.now()+45000;const {error}=await sb.from('game_rounds').update({status:'vote',deadline_at:new Date(deadline).toISOString()}).eq('id',dbRoundId);if(error)throw error;const roomResult=await sb.from('game_rooms').update({status:'vote',deadline_at:new Date(deadline).toISOString()}).eq('id',dbRoomId);if(roomResult.error)console.warn('Estado da sala não atualizado:',roomResult.error.message);game.phase='vote';game.voteDeadline=deadline;game.votes={};drawDeadlineExpired=false;drawForceVote=false;syncState();render();sendCurrentDrawings();startVoteTimer();say('Desenhos enviados. Votação aberta por 45 segundos.');if(!Object.keys(game.drawings||{}).length||validVoterCount()===0)finishRound()}catch(error){say('Não foi possível abrir a votação no servidor. '+friendlyError(error))}}
