function flushStrokeMoves(){if(moveFlushTimer){clearTimeout(moveFlushTimer);moveFlushTimer=null}if(!pendingMoves.length||!activeStroke||activeStroke.kind!=='stroke'){pendingMoves=[];return}const points=pendingMoves;pendingMoves=[];send('stroke-move',{id:player,round:game.round,strokeId:player+':'+game.round+':'+activeStroke.id,points})}
