canvas.addEventListener('contextmenu',e=>e.preventDefault());
canvas.addEventListener('pointerdown',e=>{if(game.phase!=='draw'||submitted)return;e.preventDefault();const p=getPos(e);try{canvas.setPointerCapture(e.pointerId)}catch{}if(tool==='bucket'){saveBeforeAction();fillBucket(p.x,p.y,strokeColor);broadcastSnapshot();const target=getLiveCanvas(player);if(target)paintSnapshot(target,canvas.toDataURL('image/jpeg',.75),canvasRevision,game.round);return}painting=true;saveBeforeAction();shapePreview=ctx.getImageData(0,0,canvas.width,canvas.height);if(['line','rect','ellipse'].includes(tool)){activeStroke={kind:tool,x1:p.x,y1:p.y,x2:p.x,y2:p.y,color:strokeColor,width:brushSize};return}const color=tool==='eraser'?'#ffffff':strokeColor;activeStroke={kind:'stroke',color,width:tool==='pencil'?Math.max(1,brushSize/3):brushSize,points:[p],id:crypto.randomUUID()};const point={...p,color:activeStroke.color,width:activeStroke.width};drawSegment(canvas,point,null);canvasRevision++;send('stroke-start',{id:player,round:game.round,revision:canvasRevision,strokeId:player+':'+game.round+':'+activeStroke.id,point})});
